  "headline": "FDA's records trace our supply to a plant classified OAI 274 days before the posting",
  "headline_cites": ["E16", "D1"],
  "sentences": [
    {
      "text": "Corvale East holds 553 units of levofloxacin at 32.2 a day, providing 17 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 602 units at 30.9 a day, providing 19 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "One registered plant on our labels, ASCLEMED USA INC. DBA ENOVACHEM (FEI 3001452204), received an OAI classification on 2018-09-27 per FDA inspection 1067059.",
      "cites": ["E16", "E18"]
    },
    {
      "text": "That OAI classification occurred 274 days before the posting date of 2019-06-11.",
      "cites": ["E16", "E17", "D1"]
    },
    {
      "text": "FDA issued a Warning Letter to the same plant on 2019-06-11.",
      "cites": ["E17"]
    },
    {
      "text": "The other registered plant, Dr. Reddy's Laboratories Limited -FTO III (FEI 3002949099), has only VAI inspections, most recently on 2023-10-27.",
      "cites": ["E11", "E12"]
    },
    {
      "text": "Camber Pharmaceuticals, Inc. is not on FDA's shortage list today and is the best option by rule.",
      "cites": ["E12"]
    }
  ]
}
